function makeExercise(id,sets,reps,weight,note){var base=exerciseLibrary.find(function(e){return e.id===id;})||exerciseLibrary[0];return {id:id,name:base.name,thumb:base.thumb,sets:sets,reps:reps,weight:weight||"",note:note||base.note};}
function byId(id){return document.getElementById(id);}function asList(value){if(Array.isArray(value))return value;if(typeof value==="string")return value.split(/[\s,]+/).map(function(x){return x.trim();}).filter(Boolean);return [];}function normalizeMemberData(member){if(!member)return member;member.activityIds=asList(member.activityIds);return member;}function normalizeClassData(item){if(!item)return item;item.booked=asList(item.booked).map(Number).filter(Boolean);return item;}function normalizeServerData(data){if(!data)return data;if(data.members)data.members=data.members.map(normalizeMemberData);if(data.member)data.member=normalizeMemberData(data.member);if(data.classes)data.classes=data.classes.map(normalizeClassData);if(data.classItem)data.classItem=normalizeClassData(data.classItem);return data;}function activityName(id){var a=activities.find(function(x){return x.id===id;});return a?a.name:id;}function activityBadges(ids){ids=asList(ids);return ids.length?ids.map(function(id){return '<span class="activity-badge">'+activityName(id)+'</span>';}).join(''):'<span class="muted">Sin actividades</span>';}function activityCheckboxes(selectedIds,name){selectedIds=asList(selectedIds);return activities.map(function(a){return '<label class="activity-check"><input type="checkbox" name="'+name+'" value="'+a.id+'" '+(selectedIds.indexOf(a.id)>=0?'checked':'')+'> <span>'+a.name+'</span></label>';}).join('');}function getCheckedValues(name){return Array.from(document.querySelectorAll('input[name="'+name+'"]:checked')).map(function(input){return input.value;});}function selectedOperationalMember(kind){if(state.role==="member")return memberById(state.currentMemberId);var id=kind==="workout"?state.workoutMemberId:state.progressMemberId;return memberById(id)||members[0];}function memberOptionsHtml(selectedId){return members.map(function(m){return '<option value="'+m.id+'" '+(m.id===selectedId?'selected':'')+'>'+m.name+'</option>';}).join("");}function memberName(id){var m=members.find(function(x){return x.id==id;});return m?m.name:"Todos";}function routineById(id){return routines.find(function(r){return r.id==id;});}function memberById(id){return members.find(function(m){return m.id==id;});}
async function apiRequest(path,options){options=options||{};var method=(options.method||"GET").toUpperCase();var headers=Object.assign({"Content-Type":"application/json"},options.headers||{});if(method!=="GET"&&csrfToken)headers["x-csrf-token"]=csrfToken;var isFile=location.protocol==="file:";var url=isFile?"http://127.0.0.1:4173"+path:path;var response=await fetch(url,Object.assign({credentials:isFile?"include":"same-origin",headers:headers},options));var data=normalizeServerData(await response.json());if(data.csrfToken)csrfToken=data.csrfToken;if(!response.ok)throw new Error(data.error||"Error del servidor");return data;}
async function hydrateStoredData(){try{var data=await apiRequest("/api/session");apiOnline=true;activities=data.activities||activities;classSessions=data.classes||classSessions;newsItems=data.news||newsItems;paymentLink=data.paymentLink||paymentLink;paymentInfo=data.paymentInfo||paymentInfo;paymentProofs=data.paymentProofs||paymentProofs;if(data.user){state.role=data.user.role;state.loggedIn=true;if(data.members)members=data.members;if(data.member){members=[data.member];state.currentMemberId=data.member.id;}document.body.className="logged-in";}}catch(e){apiOnline=false;}try{var savedNews=localStorage.getItem(newsStorageKey);if(savedNews)newsItems=JSON.parse(savedNews);if(!apiOnline){var savedMembers=localStorage.getItem(storageKey);if(savedMembers)members=JSON.parse(savedMembers);var savedClasses=localStorage.getItem(classStorageKey);if(savedClasses)classSessions=JSON.parse(savedClasses);restoreLocalSession();}}catch(e){}}
function persistMembers(){try{localStorage.setItem(storageKey,JSON.stringify(members));}catch(e){}}
function persistClasses(){try{localStorage.setItem(classStorageKey,JSON.stringify(classSessions));}catch(e){}}
function persistNews(){try{localStorage.setItem(newsStorageKey,JSON.stringify(newsItems));}catch(e){}}
function persistLocalSession(){try{localStorage.setItem(localSessionKey,JSON.stringify({role:state.role,currentMemberId:state.currentMemberId,view:state.view,loggedIn:state.loggedIn}));}catch(e){}}
function clearLocalSession(){try{localStorage.removeItem(localSessionKey);}catch(e){}}
// La sesion NO se restaura desde localStorage: estar logueado exige una sesion real del server.
// Asi nadie puede fabricar una shell de admin escribiendo {role:"admin",loggedIn:true} en el storage.
function restoreLocalSession(){clearLocalSession();}
function normalizeUser(value){return (value||"").toLowerCase().trim().replace(/\s+/g,".");}
function userExists(user){user=normalizeUser(user);return staffUsers.some(function(u){return normalizeUser(u.user)===user;})||members.some(function(m){return normalizeUser(m.user)===user;});}
function avgConsistency(){if(!members.length)return 0;return Math.round(members.reduce(function(sum,m){return sum+(m.consistency||Math.min(100,Math.round((m.attendance||0)*6)));},0)/members.length);}
function normalizePlan(type){return type==="eight-classes"||type==="non-member"?"eight-classes":"free-pass";}
function memberTypeLabel(type){return normalizePlan(type)==="eight-classes"?"8 clases":"Pase libre";}
function memberTypeSelect(member){var plan=normalizePlan(member.memberType);return '<select class="member-type-select '+plan+'" data-member-type="'+member.id+'"><option value="eight-classes" '+(plan==="eight-classes"?"selected":"")+'>8 clases</option><option value="free-pass" '+(plan==="free-pass"?"selected":"")+'>Pase libre</option></select>';}
function memberNumberValue(m){return Number(m.memberNumber)||Number(m.id)||0;}
function sortMembersNewest(a,b){return memberNumberValue(b)-memberNumberValue(a);}
function memberMatchesFilter(member){var plan=normalizePlan(member.memberType);if(state.memberFilter==="all")return true;if(state.memberFilter==="free-pass")return plan==="free-pass";if(state.memberFilter==="eight-classes")return plan==="eight-classes";if(state.memberFilter==="due")return member.payment==="due";if(state.memberFilter==="new")return member.source==="ficha";return true;}
function currentDayName(){return ["Domingo","Lunes","Martes","Miercoles","Jueves","Viernes","Sabado"][new Date().getDay()];}
function newsForToday(){var today=currentDayName();return newsItems.find(function(n){return n.day===today;})||newsItems[0];}
function newsCategory(n){if(n.category)return n.category;if(/promo/i.test(n.title))return "Promociones";if(/cambio|suspend/i.test(n.title))return "Cambios";if(/especial|evento/i.test(n.title))return "Eventos";return "Horarios";}
function escapeHtml(value){return String(value==null?"":value).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");}
function safeImageSrc(value){var v=String(value||"");if(/^data:image\/(png|jpe?g|gif|webp);base64,[a-z0-9+/=]+$/i.test(v))return v;if(/^(https?:\/\/|\/|assets\/)/i.test(v))return escapeHtml(v);return"";}
function newsCard(n,featured){var category=escapeHtml(newsCategory(n));var img=safeImageSrc(n.image);var adminActions=state.role!=="member"?'<button class="danger-button news-delete-button" type="button" data-delete-news="'+Number(n.id)+'">Eliminar</button>':'';return '<article class="news-card '+(featured?'featured':'')+'">'+(img?'<img src="'+img+'" alt="'+escapeHtml(n.title)+'">':'')+'<div><div class="news-card-top"><span><span class="tag">'+category+'</span><span class="news-day">'+escapeHtml(n.day==="Todos"?"General":n.day)+'</span></span>'+adminActions+'</div><h2>'+escapeHtml(n.title)+'</h2><p>'+escapeHtml(n.text)+'</p></div></article>';}
function showSignupPage(){document.body.className="registering";byId("signupError").textContent="";var name=byId("signupFullName");if(name)name.focus();}
function showLoginPage(){document.body.className="logged-out";byId("signupError").textContent="";byId("loginError").textContent="";resetSignupVerification();}
async function init(){await hydrateStoredData();bindStaticEvents();try{renderNav();renderAll();}catch(e){console.error("No se pudo dibujar la pantalla inicial",e);}if(state.loggedIn){showView(state.view);}else if(document.body.classList.contains("registering")||location.hash==="#registro"){showSignupPage();}else{showLoginPage();}}
function renderAll(){renderDashboard();renderNews();renderConexionPostural();renderMembers();renderRoutines();renderSchedule();renderPayments();renderAccounting();renderWorkout();renderProgress();renderProfile();fillSelects();updateRoleChrome();}
function renderNav(){var nav=byId("navList");nav.innerHTML="";navByRole[state.role].forEach(function(view){var b=document.createElement("button");b.className="nav-item"+(state.view===view?" active":"");b.dataset.view=view;b.type="button";b.innerHTML='<span class="nav-icon">'+(navIcons[view]||"--")+'</span><span>'+titles[view]+'</span>';b.addEventListener("click",function(){showView(view);});nav.appendChild(b);});}
function showView(view){if(navByRole[state.role].indexOf(view)===-1&&view!=="memberDetail"&&view!=="routineDetail"){view=navByRole[state.role][0];}state.view=view;document.querySelectorAll(".view").forEach(function(s){s.classList.remove("active");});byId(view).classList.add("active");document.querySelectorAll(".nav-item").forEach(function(n){n.classList.toggle("active",n.dataset.view===view);});byId("viewTitle").textContent=titles[view];if(state.loggedIn&&!apiOnline)persistLocalSession();}
function updateRoleChrome(){byId("roleLabel").textContent=roleLabels[state.role];byId("roleHint").textContent=state.role==="member"?"Vista socio":"Panel simple";document.querySelectorAll(".role-button").forEach(function(b){b.classList.toggle("active",b.dataset.role===state.role);});var adminActions=state.role!=="member";byId("topActions").classList.toggle("hidden",!adminActions);}
function memberDashboardHtml(m){var myClasses=classSessions.slice().sort(function(a,b){return a.day.localeCompare(b.day)||a.time.localeCompare(b.time);});var today=newsForToday();var next=myClasses[0];var attendanceGoal=12;var attendancePct=Math.min(100,Math.round(((m.attendance||0)/attendanceGoal)*100));var streak=Math.max(1,Math.min(9,Math.round((m.consistency||m.attendance||7)/3)));var paymentState=m.payment==="paid"?"Al dia":"Pendiente";var nextText=next?next.day+" "+next.time:"Sin clases cargadas";var payCta=m.payment==="due"?'<button class="pay-now-button" type="button" onclick="showView(\'payments\')"><span>$</span><strong>Ver pagos</strong></button>':'<div class="paid-pill">Cuota al dia</div>';var miniClasses=myClasses.slice(0,4).map(function(c){return '<div class="mini-class"><span>'+c.time+'</span><div><strong>'+c.title+'</strong><small>'+c.day+'</small></div></div>';}).join("");return '<div class="member-home member-home-v2"><section class="panel member-week"><div><p class="eyebrow">Esta semana</p><h2>'+m.name+'</h2></div><div class="week-grid"><div><span>Cuota</span><strong class="'+(m.payment==="paid"?"ok-text":"due-text")+'">'+paymentState+'</strong><small>'+((m.payment==="paid")?"Sin accion pendiente":"Resolver en Pagos")+'</small></div><div><span>Proxima clase</span><strong>'+nextText+'</strong><small>'+myClasses.length+' clases disponibles</small></div><div><span>Asistencia del mes</span><strong>'+m.attendance+'/'+attendanceGoal+'</strong><small>'+(attendancePct>=70?"+ buena constancia":"A reforzar")+'</small></div><div><span>Racha</span><strong>'+streak+' dias</strong><small>Segui asi</small></div></div><div class="week-progress"><span style="width:'+attendancePct+'%"></span></div>'+payCta+'</section><section class="panel member-agenda"><div class="member-flyer-small">'+newsCard(today,false)+'</div><aside class="next-classes"><div class="panel-heading"><div><p class="eyebrow">Agenda</p><h2>Proximas clases</h2></div><button class="ghost-button" type="button" onclick="showView(\'routines\')">Ver calendario</button></div><div class="mini-class-list">'+(miniClasses||'<div class="empty-state">Todavia no hay clases cargadas.</div>')+'</div></aside></section><section class="panel member-quick-progress"><div class="panel-heading"><div><p class="eyebrow">Constancia</p><h2>Tu mes</h2></div><strong>'+attendancePct+'%</strong></div><div class="fitness-meter"><span style="width:'+attendancePct+'%"></span></div><p class="muted">Asistencias registradas sobre el objetivo mensual.</p></section></div>';}function renderDashboard(){var el=byId("dashboard");if(state.role==="member"){var m=memberById(state.currentMemberId);el.innerHTML=memberDashboardHtml(m);return;}var active=members.filter(function(m){return m.payment==="paid";});var due=members.filter(function(m){return m.payment==="due";});var free=members.filter(function(m){return normalizePlan(m.memberType)==="free-pass";}).length;var eight=members.filter(function(m){return normalizePlan(m.memberType)==="eight-classes";}).length;var total=members.length||1;var freePct=Math.round((free/total)*100);var eightPct=Math.round((eight/total)*100);var today=new Date().toISOString().slice(0,10);var recent=members.slice().sort(sortMembersNewest).slice(0,6);el.innerHTML='<div class="metrics-grid dashboard-business"><article class="metric"><span>Socios activos</span><strong>'+active.length+'</strong><small><b>'+members.length+' totales</b> Activos = cuota al dia</small></article><article class="metric"><span>Pase libre</span><strong>'+freePct+'%</strong><small><b>'+free+' socios</b> Abono mensual libre</small></article><article class="metric"><span>8 clases</span><strong>'+eightPct+'%</strong><small><b>'+eight+' socios</b> Abono mensual limitado</small></article><article class="metric"><span>Cuotas pendientes</span><strong>'+due.length+'</strong><small><b>'+(due.length?"Revisar pagos":"Todo al dia")+'</b> A la fecha '+today+'</small></article></div><div class="split-layout dashboard-business-lower"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">Altas recientes</p><h2>Socios a la fecha</h2></div><button class="text-button" type="button" onclick="showView(\'members\')">Ver socios</button></div><div class="activity-list">'+(recent.length?recent.map(function(m){return '<div class="activity-row"><div class="avatar">'+initials(m.name)+'</div><div><strong>'+memberNumberLabel(m)+' - '+m.name+'</strong><span>'+memberTypeLabel(m.memberType)+' - '+(m.source==="ficha"?"Ficha publica":"Carga manual")+'</span></div><time>'+(m.payment==="paid"?"Al dia":"Pendiente")+'</time></div>';}).join(""):'<div class="empty-state">Todavia no hay socios cargados.</div>')+'</div></section><section class="panel"><div class="panel-heading"><div><p class="eyebrow">Abonos</p><h2>Distribucion</h2></div></div><div class="progress-list"><div><span>Pase libre</span><strong>'+free+' socios</strong></div><div class="fitness-meter"><span style="width:'+freePct+'%"></span></div><div><span>8 clases</span><strong>'+eight+' socios</strong></div><div class="fitness-meter"><span style="width:'+eightPct+'%"></span></div><div><span>Pendientes</span><strong>'+due.length+' cuotas</strong></div></div></section></div>';}
function renderRegistrations(){var el=byId("registrations");if(!el)return;if(state.role!=="admin"){el.innerHTML='<div class="empty-state">Solo administradores pueden ver fichas de inscripcion.</div>';return;}var rows=members.filter(function(m){return m.source==="ficha";}).sort(sortMembersNewest);el.innerHTML='<div class="toolbar"><div><p class="member-note">Registros creados desde la ficha publica. Desde aca la admin puede revisar datos personales, contacto y observaciones corporales.</p></div><button class="primary-button" type="button" onclick="showSignupPage()">Abrir ficha publica</button></div><div class="table-panel"><table><thead><tr><th>#</th><th>Socio</th><th>DNI</th><th>Mail</th><th>Usuario</th><th>Fecha</th><th>Cuota</th><th></th></tr></thead><tbody>'+rows.map(function(m){return '<tr class="clickable" data-member-row="'+m.id+'">'+cell("#",memberNumberLabel(m))+cell("Socio",m.name)+cell("DNI",m.dni||"-")+cell("Mail",m.email||"-")+cell("Usuario",m.user)+cell("Fecha",m.registeredAt||"-")+cell("Cuota",paymentSelect(m))+cell("",'<button class="ghost-button" data-member-detail="'+m.id+'" type="button">Ver ficha</button>')+'</tr>';}).join("")+'</tbody></table></div>'+(rows.length?'':'<div class="empty-state">Todavia no hay inscripciones publicas cargadas.</div>');bindMemberRows();bindPaymentSelects();}
function renderMembers(){var el=byId("members");if(state.role==="member"){el.innerHTML='<div class="empty-state">Esta seccion no esta disponible para socios.</div>';return;}var showPass=state.role==="admin";var filters=[["all","Todos"],["free-pass","Pase libre"],["eight-classes","8 clases"],["due","Cuota pendiente"],["new","Nuevos"]];var orderedMembers=members.slice().sort(sortMembersNewest);el.innerHTML='<div class="toolbar members-toolbar"><label class="search"><span>Buscar</span><input id="memberSearch" type="search" placeholder="Numero, nombre, usuario o DNI" value="'+state.memberQuery+'"></label><div class="filter-tabs">'+filters.map(function(f){return '<button class="ghost-button '+(state.memberFilter===f[0]?'is-selected':'')+'" type="button" data-member-filter="'+f[0]+'">'+f[1]+'</button>';}).join("")+'</div><button class="primary-button" id="addMemberButton" type="button">Agregar socio</button></div><div class="table-panel"><table><thead><tr><th>#</th><th>Socio</th><th>Abono</th><th>Usuario</th>'+(showPass?'<th>Acceso</th>':'')+'<th>Cuota</th><th>Vencimiento</th><th>Origen</th><th></th></tr></thead><tbody id="membersBody">'+orderedMembers.map(memberRow).join("")+'</tbody></table></div><div class="empty-state hidden" id="noMembersFound">No hay socios con ese filtro o busqueda.</div>';var input=byId("memberSearch");input.addEventListener("input",function(e){state.memberQuery=e.target.value;filterMemberRows();});document.querySelectorAll("[data-member-filter]").forEach(function(btn){btn.addEventListener("click",function(){state.memberFilter=btn.dataset.memberFilter;renderMembers();});});byId("addMemberButton").addEventListener("click",openMemberModal);bindMemberRows();bindPaymentSelects();bindMemberTypeSelects();filterMemberRows();}
function filterMemberRows(){var q=state.memberQuery.toLowerCase();var visible=0;document.querySelectorAll("#membersBody tr").forEach(function(row){var m=memberById(Number(row.dataset.memberRow));var ok=row.dataset.search.includes(q)&&m&&memberMatchesFilter(m);row.classList.toggle("hidden",!ok);if(ok)visible++;});var empty=byId("noMembersFound");if(empty)empty.classList.toggle("hidden",visible!==0);}
function bindMemberRows(){document.querySelectorAll("[data-member-detail]").forEach(function(b){b.addEventListener("click",function(e){e.stopPropagation();openMemberDetail(Number(b.dataset.memberDetail));});});document.querySelectorAll("tr[data-member-row]").forEach(function(row){row.addEventListener("click",function(){openMemberDetail(Number(row.dataset.memberRow));});});}
function paymentSelect(member){return '<select class="payment-select '+(member.payment==="paid"?"paid":"due")+'" data-payment-member="'+member.id+'"><option value="paid" '+(member.payment==="paid"?"selected":"")+'>Al dia</option><option value="due" '+(member.payment==="due"?"selected":"")+'>Pendiente</option></select>';}
function reminderText(member){return member.lastPaymentReminder?member.lastPaymentReminder:"Sin recordatorio registrado";}
function paymentLinkForMember(member){var plan=normalizePlan(member&&member.memberType);return paymentLinks[plan]||paymentLink;}
function paymentInfoCard(withUpload,member){var plan=normalizePlan(member&&member.memberType);var planLabel=member?memberTypeLabel(member.memberType):"online";var price=plan==="eight-classes"?"$38.000":"$49.000";var link=paymentLinkForMember(member);return '<div class="payment-checkout"><div class="payment-plan-card '+plan+'"><div><span>Abono seleccionado</span><strong>'+planLabel+'</strong><small>Link oficial de Mercado Pago</small></div><div class="payment-price">'+price+'</div></div><div class="pay-data-card"><div><span>Alias</span><strong>'+paymentInfo.alias+'</strong><button class="ghost-button small-button" type="button" data-copy-value="'+paymentInfo.alias+'">Copiar</button></div><div><span>CVU</span><strong>'+paymentInfo.cvu+'</strong><button class="ghost-button small-button" type="button" data-copy-value="'+paymentInfo.cvu+'">Copiar</button></div><div><span>Titular</span><strong>'+paymentInfo.holder+'</strong></div></div><div class="payment-cta-row"><a class="primary-button pay-card-button" href="'+link+'" target="_blank" rel="noreferrer">Pagar '+planLabel+'</a>'+(withUpload?'<label class="ghost-button proof-upload-button">Subir comprobante<input type="file" accept="image/*" hidden onchange="uploadPaymentProof(this)"></label>':'')+'</div></div>';}
function copyText(value){navigator.clipboard&&navigator.clipboard.writeText?navigator.clipboard.writeText(value).then(function(){toast("Copiado");}).catch(function(){toast(value);}):toast(value);}
function proofStatusLabel(status){return String(status||"Pendiente").toLowerCase().indexOf("aprob")>=0?"Aprobado":"Pendiente";}
async function updatePaymentStatus(id,value){var m=memberById(Number(id));if(!m)return;var previous=m.payment;m.payment=value;if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"PATCH",body:JSON.stringify({payment:value})});if(data.members)members=data.members;}catch(e){m.payment=previous;renderAll();showView(state.view);toast(e.message);return;}}else{persistMembers();}renderAll();if(state.view==="memberDetail"&&state.selectedMemberId===m.id){renderMemberDetail();showView("memberDetail");}else{showView(state.view);}toast("Estado de cuota actualizado");}
async function updateMemberType(id,value){var m=memberById(Number(id));if(!m)return;m.memberType=value;if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"PATCH",body:JSON.stringify({memberType:value})});if(data.members)members=data.members;}catch(e){toast(e.message);}}else{persistMembers();}renderAll();if(state.view==="memberDetail"&&state.selectedMemberId===m.id){renderMemberDetail();showView("memberDetail");}else{showView(state.view);}toast("Tipo de abono actualizado");}
function bindPaymentSelects(){document.querySelectorAll("[data-payment-member]").forEach(function(select){select.addEventListener("click",function(e){e.stopPropagation();});select.addEventListener("change",function(e){e.stopPropagation();updatePaymentStatus(select.dataset.paymentMember,select.value);});});}
function bindMemberTypeSelects(){document.querySelectorAll("[data-member-type]").forEach(function(select){select.addEventListener("click",function(e){e.stopPropagation();});select.addEventListener("change",function(e){e.stopPropagation();updateMemberType(select.dataset.memberType,select.value);});});}
function cell(label,content){return '<td data-label="'+label+'">'+content+'</td>';}
function memberNumberLabel(m){return '#'+(m.memberNumber||m.id);}
function memberRow(m){var pass=state.role==="admin"?cell("Acceso",'<span class="credential-pill">Protegida</span>'):'';return '<tr class="clickable" data-member-row="'+m.id+'" data-search="'+(memberNumberLabel(m)+' '+m.name+' '+m.user+' '+(m.dni||'')).toLowerCase()+'">'+cell("#",memberNumberLabel(m))+cell("Socio",m.name)+cell("Abono",memberTypeSelect(m))+cell("Usuario",m.user)+pass+cell("Cuota",paymentSelect(m))+cell("Vencimiento",m.dueDate||"-")+cell("Origen",m.source==="ficha"?"Ficha":"Manual")+cell("",'<button class="ghost-button" data-member-detail="'+m.id+'" type="button">Ver ficha</button>')+'</tr>';}
function openMemberDetail(id){state.selectedMemberId=id;renderMemberDetail();showView("memberDetail");}
function renderMemberDetail(){var m=memberById(state.selectedMemberId)||members[0];var back=state.view==="registrations"?"registrations":"members";var passwordPanel=state.role==="admin"?'<section class="panel"><div class="panel-heading"><h2>Acceso del socio</h2></div><p class="muted">Por seguridad, la contrasena no se puede ver. El admin solo puede generar una nueva.</p><div class="password-form"><label class="field"><span>Usuario actual</span><input value="'+m.user+'" disabled></label><label class="field"><span>Nueva contrasena</span><div class="password-field"><input id="memberPasswordInput" type="password" value="" placeholder="Minimo 6 caracteres"><button class="eye-button" type="button" data-toggle-password="memberPasswordInput" aria-label="Ver contrasena">Ver</button></div></label><button class="primary-button" type="button" onclick="updateMemberPassword('+m.id+')">Resetear contrasena</button></div></section>':'';var deletePanel=state.role==="admin"?'<section class="panel danger-zone"><div><p class="eyebrow">Zona sensible</p><h2>Eliminar socio</h2><p class="muted">Borra la ficha y quita sus reservas de clases. Esta accion no se puede deshacer.</p></div><button class="danger-button" type="button" onclick="deleteMember('+m.id+')">Eliminar socio</button></section>':'';byId("memberDetail").innerHTML='<div class="detail-actions"><button class="ghost-button" type="button" onclick="showView(\''+back+'\')">Volver</button><button class="primary-button" type="button" onclick="openAssignModal('+(m.routineId||1)+')">Asignar actividades</button></div><div class="detail-grid"><section class="panel"><div class="panel-heading"><div><p class="eyebrow">Ficha editable</p><h2>'+m.name+'</h2></div><div class="payment-detail"><span>Cuota</span>'+paymentSelect(m)+'</div></div><div class="form-grid two"><label class="field"><span>Nombre completo</span><input id="editMemberName" value="'+(m.name||"")+'" required minlength="2" maxlength="90"></label><label class="field"><span>Usuario</span><input id="editMemberUser" value="'+(m.user||"")+'" required minlength="2" maxlength="40" pattern="[A-Za-z0-9._-]+"></label></div><div class="form-grid two"><label class="field"><span>DNI</span><input id="editMemberDni" value="'+(m.dni||"")+'" inputmode="numeric" maxlength="20" pattern="[0-9.\\-]+"></label><label class="field"><span>Fecha de nacimiento</span><input id="editMemberBirthdate" type="date" value="'+(m.birthdate||"")+'"></label></div><label class="field"><span>Mail</span><input id="editMemberEmail" type="email" value="'+(m.email||"")+'" maxlength="120"></label><div class="form-grid two"><label class="field"><span>Tipo de abono</span><select id="editMemberType"><option value="eight-classes" '+(normalizePlan(m.memberType)==="eight-classes"?"selected":"")+'>8 clases</option><option value="free-pass" '+(normalizePlan(m.memberType)==="free-pass"?"selected":"")+'>Pase libre</option></select></label><label class="field"><span>Fecha de vencimiento</span><input id="editMemberDueDate" type="date" value="'+(m.dueDate||"")+'"></label></div><label class="field"><span>Patologia, enfermedad, dolor o estado corporal actual</span><textarea id="editMemberBodyNote" maxlength="800">'+(m.bodyNote||"")+'</textarea></label><button class="primary-button wide" type="button" onclick="updateMemberDetails('+m.id+')">Guardar cambios</button></section><section class="panel"><div class="panel-heading"><h2>Resumen operativo</h2></div><div class="progress-list"><div><span>Numero</span><strong>'+memberNumberLabel(m)+'</strong></div><div><span>Asistencias</span><strong>'+m.attendance+'</strong></div><div><span>Origen</span><strong>'+(m.source==="ficha"?"Ficha publica":"Carga manual")+'</strong></div><div><span>Registro</span><strong>'+(m.registeredAt||"-")+'</strong></div><div><span>Tipo</span><strong>'+memberTypeLabel(m.memberType)+'</strong></div><div><span>Estado</span><strong>'+(m.payment==="paid"?"Al dia":"Pendiente")+'</strong></div><div><span>Vencimiento</span><strong>'+(m.dueDate||"Sin fecha")+'</strong></div><div><span>Ultimo pago</span><strong>'+(m.lastPayment||"Sin registro")+'</strong></div><div><span>Ultimo recordatorio</span><strong>'+reminderText(m)+'</strong></div></div></section>'+passwordPanel+deletePanel+'</div>';bindPaymentSelects();}
async function updateMemberActivities(id){var m=memberById(id);if(m){m.activityIds=getCheckedValues("detailActivities");if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"PATCH",body:JSON.stringify({activityIds:m.activityIds})});if(data.members)members=data.members;}catch(e){toast(e.message);}}else{persistMembers();}renderMemberDetail();renderMembers();renderRegistrations();toast("Actividades actualizadas");}}
async function updateMemberDetails(id){var m=memberById(id);if(!m)return;var payload={name:byId("editMemberName").value.trim(),user:normalizeUser(byId("editMemberUser").value.trim()),dni:byId("editMemberDni").value.trim(),birthdate:byId("editMemberBirthdate").value,email:byId("editMemberEmail").value.trim(),memberType:byId("editMemberType").value,dueDate:byId("editMemberDueDate").value,bodyNote:byId("editMemberBodyNote").value.trim(),activityIds:asList(m.activityIds)};if(!payload.name||!payload.user){toast("Nombre y usuario son obligatorios");return;}Object.assign(m,payload);if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"PATCH",body:JSON.stringify(payload)});if(data.members)members=data.members;}catch(e){toast(e.message);return;}}else{persistMembers();}renderAll();state.selectedMemberId=id;renderMemberDetail();showView("memberDetail");toast("Ficha actualizada");}
async function updateMemberPassword(id){var m=memberById(id);var input=byId("memberPasswordInput");if(m&&input){var newPassword=input.value.trim();if(newPassword.length<6){toast("Minimo 6 caracteres");return;}if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"PATCH",body:JSON.stringify({password:newPassword})});if(data.members)members=data.members;}catch(e){toast(e.message);return;}}else{m.password=newPassword;persistMembers();}input.value="";renderMemberDetail();renderMembers();renderRegistrations();toast("Contrasena reseteada");}}
async function deleteMember(id){var m=memberById(id);if(!m)return;if(state.role!=="admin"){toast("Solo admin puede eliminar socios");return;}if(!confirm("Eliminar a "+m.name+"? Se borra su ficha y sus reservas."))return;if(apiOnline){try{var data=await apiRequest("/api/members/"+m.id,{method:"DELETE"});if(data.members)members=data.members;if(data.classes)classSessions=data.classes;}catch(e){toast(e.message);return;}}else{members=members.filter(function(item){return item.id!==m.id;});classSessions.forEach(function(c){c.booked=(c.booked||[]).filter(function(memberId){return Number(memberId)!==m.id;});});persistMembers();persistClasses();}state.selectedMemberId=null;renderAll();showView("members");toast("Socio eliminado");}
async function sendPaymentReminder(id,button){var m=memberById(id);if(!m)return;if(!apiOnline){toast("Los mails requieren servidor activo");return;}if(button){button.disabled=true;button.textContent="Enviando...";}try{var data=await apiRequest("/api/members/"+m.id+"/payment-reminder",{method:"POST",body:"{}"});if(data.members)members=data.members;renderPayments();toast("Recordatorio enviado a "+m.name);}catch(e){toast(e.message);}finally{if(button){button.disabled=false;button.textContent="Enviar recordatorio";}}}
async function sendMonthlyPaymentReminders(button){if(!apiOnline){toast("Los mails requieren servidor activo");return;}if(button){button.disabled=true;button.textContent="Enviando...";}try{var data=await apiRequest("/api/payment-reminders/run",{method:"POST",body:"{}"});if(data.members)members=data.members;renderPayments();toast("Recordatorios enviados: "+(data.sent||0));}catch(e){toast(e.message);}finally{if(button){button.disabled=false;button.textContent="Enviar pendientes del mes";}}}
async function uploadPaymentProof(input){var file=input.files&&input.files[0];if(!file)return;if(!apiOnline){toast("La subida requiere servidor activo");input.value="";return;}if(file.size>5000000){toast("La imagen es muy pesada. Usa una captura menor a 5 MB.");input.value="";return;}var reader=new FileReader();reader.onload=async function(){try{var data=await apiRequest("/api/payment-proofs",{method:"POST",body:JSON.stringify({image:reader.result,note:"Comprobante subido desde el panel del socio"})});paymentProofs=data.paymentProofs||paymentProofs;renderAll();showView(state.view);toast("Comprobante enviado para revision");}catch(e){toast(e.message);}finally{input.value="";}};reader.readAsDataURL(file);}
async function approvePaymentProof(id){if(!apiOnline){toast("Requiere servidor activo");return;}try{var data=await apiRequest("/api/payment-proofs/"+id+"/approve",{method:"POST",body:"{}"});members=data.members||members;paymentProofs=data.paymentProofs||paymentProofs;renderAll();showView("payments");toast("Pago aprobado y cuota actualizada");}catch(e){toast(e.message);}}
async function deletePaymentProof(id){if(state.role!=="admin"){toast("Solo admin puede eliminar comprobantes");return;}if(!confirm("Eliminar este comprobante de la lista?"))return;if(apiOnline){try{var data=await apiRequest("/api/payment-proofs/"+id,{method:"DELETE"});paymentProofs=data.paymentProofs||paymentProofs;}catch(e){toast(e.message);return;}}else{paymentProofs=paymentProofs.filter(function(p){return Number(p.id)!==Number(id);});}renderAll();showView("payments");toast("Comprobante eliminado");}
function openProofModal(id){var proof=paymentProofs.find(function(p){return Number(p.id)===Number(id);});if(!proof||!proof.image){toast("No hay imagen disponible");return;}var modal=byId("proofModal");var img=byId("proofModalImage");var title=byId("proofModalTitle");if(title)title.textContent="Comprobante - "+(proof.memberName||"Socio");if(img)img.src=proof.image;if(modal)modal.showModal();}
async function deleteNews(id){if(!id)return;if(!confirm("Eliminar esta novedad?"))return;if(apiOnline){try{var data=await apiRequest("/api/news/"+id,{method:"DELETE"});newsItems=data.news||newsItems;}catch(e){toast(e.message);return;}}else{newsItems=newsItems.filter(function(item){return Number(item.id)!==Number(id);});persistNews();}renderNews();toast("Novedad eliminada");}
function toast(message){var old=document.querySelector(".mini-toast");if(old)old.remove();var el=document.createElement("div");el.className="mini-toast";el.textContent=message;document.body.appendChild(el);setTimeout(function(){el.remove();},1800);}
document.addEventListener("pointerdown",function(e){var btn=e.target.closest(".primary-button,.ghost-button,.danger-button,.pay-now-button");if(!btn)return;var rect=btn.getBoundingClientRect();btn.style.setProperty("--rx",(e.clientX-rect.left)+"px");btn.style.setProperty("--ry",(e.clientY-rect.top)+"px");});
document.addEventListener("click",function(e){var btn=e.target.closest("[data-copy-value]");if(btn){e.preventDefault();copyText(btn.dataset.copyValue);}});
function assignRoutineToCurrentMember(id){var m=memberById(state.currentMemberId);if(m){m.routineId=id;renderAll();showView("workout");toast("Rutina asignada a tu entrenamiento");}}
function classById(id){return classSessions.find(function(c){return c.id===id;});}
function classRow(c){return '<div class="class-row"><div><span class="tag">'+activityName(c.activityId)+'</span><strong>'+c.title+'</strong><small>'+c.day+' '+c.time+' - '+c.coach+'</small></div></div>';}
function classCard(c){return '<article class="routine-card class-card"><div class="routine-image '+(c.activityId==='spinning'?'fullbody':c.activityId==='conexion'?'mobility':'strength')+'"></div><div><span class="tag">'+activityName(c.activityId)+'</span><h2>'+c.title+'</h2><p>'+c.focus+'</p><p class="muted">'+c.day+' '+c.time+' - '+c.coach+'</p><div class="card-actions"><button class="ghost-button" data-class-detail="'+c.id+'" type="button">Ver detalle</button></div></div></article>';}
function scheduleItem(c){return '<article class="schedule-item"><button class="schedule-card-main" type="button" data-class-detail="'+c.id+'"><span class="schedule-time">'+c.time+'</span><strong>'+c.title+'</strong><small>'+activityName(c.activityId)+' - '+c.coach+'</small></button></article>';}
function renderSchedule(){var el=byId("schedule");if(!el)return;if(state.role==="member"){el.innerHTML='<div class="empty-state">Los socios ven sus horarios desde Clases.</div>';return;}var days=["Lunes","Martes","Miercoles","Jueves","Viernes","Sabado","Domingo"];el.innerHTML='<div class="schedule-header panel"><div><p class="eyebrow">Planilla semanal</p><h2>Horarios por dia</h2><p class="muted">Cada columna representa un dia. Agrega clases desde el boton del dia o toca una tarjeta para ver el detalle.</p></div><button class="primary-button" type="button" data-open-class-modal>Nueva clase</button></div><div class="schedule-calendar">'+days.map(function(day){var items=classSessions.filter(function(c){return c.day===day;}).sort(function(a,b){return a.time.localeCompare(b.time);});return '<section class="schedule-day"><div class="schedule-day-head"><div><h2>'+day+'</h2><span>'+items.length+' clases</span></div><button class="ghost-button schedule-add" type="button" data-open-class-day="'+day+'">Agregar</button></div><div class="schedule-list">'+(items.length?items.map(scheduleItem).join(""):'<div class="schedule-empty">Sin clases</div>')+'</div></section>';}).join("")+'</div>';var newClass=el.querySelector("[data-open-class-modal]");if(newClass)newClass.addEventListener("click",openClassModal);el.querySelectorAll("[data-open-class-day]").forEach(function(btn){btn.addEventListener("click",function(){openClassModal(btn.dataset.openClassDay);});});el.querySelectorAll("[data-class-detail]").forEach(function(btn){btn.addEventListener("click",function(){openClassDetail(Number(btn.dataset.classDetail));});});}
function paymentCard(m){var reminder=m.payment==="due"?'<button class="primary-button" type="button" data-payment-reminder="'+m.id+'">Enviar recordatorio</button>':'';return '<article class="payment-card '+(m.payment==="paid"?"is-paid":"is-due")+'"><div><span class="payment-state">'+(m.payment==="paid"?"Al dia":"Pendiente")+'</span><h2>'+m.name+'</h2><p>'+memberTypeLabel(m.memberType)+' - '+(m.email||"Sin mail")+'</p><small class="muted">Vence: '+(m.dueDate||"Sin fecha")+' - Ultimo pago: '+(m.lastPayment||"Sin registro")+' - Recordatorio: '+reminderText(m)+'</small><div class="activity-badge-list">'+activityBadges(m.activityIds)+'</div></div><div class="payment-actions">'+paymentSelect(m)+reminder+'<button class="ghost-button" type="button" data-member-detail="'+m.id+'">Ver ficha</button></div></article>';}
function paymentProofCard(p){var status=proofStatusLabel(p.status);var admin=state.role!=="member";var thumb=p.image&&admin?'<button class="proof-thumb" type="button" onclick="openProofModal('+p.id+')" aria-label="Ver comprobante de '+escapeHtml(p.memberName)+'"><img src="'+p.image+'" alt="Comprobante de '+escapeHtml(p.memberName)+'"><span>Ver</span></button>':'';var actions=admin?'<div class="payment-actions"><button class="ghost-button" type="button" onclick="openProofModal('+p.id+')">Ver comprobante</button>'+(status==="Aprobado"?'<span class="paid-pill">Aprobado</span>':'<button class="primary-button" type="button" onclick="approvePaymentProof('+p.id+')">Aprobar pago</button>')+'<button class="ghost-button" type="button" data-member-detail="'+p.memberId+'">Ver socio</button>'+(state.role==="admin"?'<button class="danger-button" type="button" onclick="deletePaymentProof('+p.id+')">Eliminar</button>':'')+'</div>':'<div class="payment-actions"><span class="'+(status==="Aprobado"?"paid-pill":"status due")+'">'+status+'</span></div>';return '<article class="proof-card '+(status==="Aprobado"?"approved":"pending")+'">'+thumb+'<div><span class="payment-state">'+status+'</span><h2>'+(admin?escapeHtml(p.memberName):"Comprobante enviado")+'</h2><p>'+(p.note||"Comprobante enviado por el socio")+'</p><small class="muted">Recibido: '+(p.createdAt||"-")+'</small></div>'+actions+'</article>';}
function renderPayments(){var el=byId("payments");if(!el)return;if(state.role==="member"){var m=memberById(state.currentMemberId)||members[0];var mine=paymentProofs.filter(function(p){return Number(p.memberId)===Number(m.id);});el.innerHTML='<div class="member-pay-page"><section class="panel member-payment-hero"><div><p class="eyebrow">Pagos</p><h2>'+(m.payment==="paid"?"Tu cuota esta al dia":"Tu cuota figura pendiente")+'</h2><p class="muted">'+(m.payment==="paid"?"No tenes pagos pendientes. Cuando se acerque el vencimiento vas a poder verlo aca.":"Podes pagar por Mercado Pago o transferencia y subir el comprobante para que administracion lo revise.")+'</p></div><span class="status '+(m.payment==="paid"?"paid":"due")+'">'+(m.payment==="paid"?"Al dia":"Pendiente")+'</span></section>'+(m.payment==="due"?'<section class="panel payment-method-panel member-only-pay"><div class="panel-heading"><div><p class="eyebrow">Datos de cobro</p><h2>Mercado Pago / transferencia</h2></div></div>'+paymentInfoCard(true,m)+'</section>':'')+'<section class="panel"><div class="panel-heading"><h2>Mis comprobantes</h2><span class="schedule-count">'+mine.length+'</span></div><div class="proof-list">'+(mine.length?mine.map(paymentProofCard).join(""):'<div class="empty-state">Todavia no subiste comprobantes.</div>')+'</div></section></div>';return;}var due=members.filter(function(m){return m.payment==="due";});var paid=members.filter(function(m){return m.payment==="paid";});var pendingProofs=paymentProofs.filter(function(p){return proofStatusLabel(p.status)==="Pendiente";});var pct=members.length?Math.round((paid.length/members.length)*100):0;el.innerHTML='<div class="payments-hero panel"><div><p class="eyebrow">Control de cuotas</p><h2>Pagos y estados</h2><p class="muted">Revisa cuotas pendientes y aproba comprobantes enviados por socios.</p></div></div><div class="metrics-grid payment-metrics"><article class="metric"><span>Al dia</span><strong>'+paid.length+'</strong><small>'+pct+'% de la base</small></article><article class="metric"><span>Pendientes</span><strong>'+due.length+'</strong><small>Requieren seguimiento</small></article><article class="metric"><span>Comprobantes</span><strong>'+pendingProofs.length+'</strong><small>Pendientes de revision</small></article><article class="metric"><span>8 clases</span><strong>'+members.filter(function(m){return normalizePlan(m.memberType)==="eight-classes";}).length+'</strong><small>Abono mensual</small></article></div><section class="panel"><div class="panel-heading"><h2>Comprobantes recibidos</h2><span class="schedule-count">'+paymentProofs.length+'</span></div><div class="proof-list">'+(paymentProofs.length?paymentProofs.map(paymentProofCard).join(""):'<div class="empty-state">Todavia no hay comprobantes cargados.</div>')+'</div></section><div class="payments-grid"><section class="panel"><div class="panel-heading"><h2>Pendientes</h2><span class="schedule-count">'+due.length+'</span></div><div class="payment-list">'+(due.length?due.map(paymentCard).join(""):'<div class="empty-state">No hay cuotas pendientes.</div>')+'</div></section><section class="panel"><div class="panel-heading"><h2>Al dia</h2><span class="schedule-count">'+paid.length+'</span></div><div class="payment-list">'+(paid.length?paid.map(paymentCard).join(""):'<div class="empty-state">Todavia no hay socios al dia.</div>')+'</div></section></div>';bindPaymentSelects();bindMemberRows();document.querySelectorAll("[data-payment-reminder]").forEach(function(btn){btn.addEventListener("click",function(){sendPaymentReminder(Number(btn.dataset.paymentReminder),btn);});});}
function renderNews(){var el=byId("news");if(!el)return;var filters=["Todos","Eventos","Cambios","Horarios","Promociones"];var visible=newsItems.filter(function(n){return state.newsFilter==="Todos"||newsCategory(n)===state.newsFilter;});var adminForm=state.role!=="member"?'<section class="panel news-admin"><div class="panel-heading"><h2>Publicar novedad</h2></div><div class="form-grid two"><label class="field"><span>Titulo</span><input id="newsTitle" placeholder="Clase especial o aviso"></label><label class="field"><span>Categoria</span><select id="newsCategory"><option>Eventos</option><option>Cambios</option><option>Horarios</option><option>Promociones</option></select></label></div><div class="form-grid two"><label class="field"><span>Dia</span><select id="newsDay"><option>Todos</option><option>Lunes</option><option>Martes</option><option>Miercoles</option><option>Jueves</option><option>Viernes</option><option>Sabado</option><option>Domingo</option></select></label><label class="field"><span>Flyer precargado</span><select id="newsImage"><option value="">Sin imagen</option><option value="assets/flyer-lunes.jpg">Flyer lunes</option><option value="assets/flyer-martes.jpg">Flyer martes</option><option value="assets/flyer-miercoles.jpg">Flyer miercoles</option><option value="assets/flyer-jueves.jpg">Flyer jueves</option><option value="assets/flyer-viernes.jpg">Flyer viernes</option><option value="assets/flyer-sabado.jpg">Flyer sabado</option></select></label></div><div class="upload-row"><label class="field upload-field"><span>Subir imagen propia</span><input id="newsUpload" type="file" accept="image/*"><small>Si subis una imagen, reemplaza al flyer precargado para esta novedad.</small></label><div class="upload-preview" id="newsUploadPreview"><span>Vista previa</span></div></div><label class="field"><span>Descripcion</span><input id="newsText" placeholder="Texto corto para los socios"></label><button class="primary-button" type="button" id="addNewsButton">Publicar</button></section>':'';el.innerHTML='<div class="news-topline"><div><p class="eyebrow">Feed OFIT</p><h2>Novedades para socios</h2></div></div><div class="news-filters">'+filters.map(function(f){return '<button class="ghost-button '+(state.newsFilter===f?'is-selected':'')+'" type="button" data-news-filter="'+f+'">'+f+'</button>';}).join("")+'</div>'+adminForm+'<div class="news-grid news-grid-feed">'+(visible.length?visible.map(function(n){return newsCard(n,false);}).join(""):'<div class="empty-state">No hay novedades en este filtro.</div>')+'</div>';document.querySelectorAll("[data-news-filter]").forEach(function(btn){btn.addEventListener("click",function(){state.newsFilter=btn.dataset.newsFilter;renderNews();});});document.querySelectorAll("[data-delete-news]").forEach(function(btn){btn.addEventListener("click",function(e){e.stopPropagation();deleteNews(Number(btn.dataset.deleteNews));});});var upload=byId("newsUpload");if(upload)upload.addEventListener("change",function(){var file=upload.files&&upload.files[0];if(!file)return;if(file.size>5000000){toast("La imagen es muy pesada. Proba con una menor a 5 MB.");upload.value="";return;}var reader=new FileReader();reader.onload=function(){upload.dataset.image=reader.result;var preview=byId("newsUploadPreview");if(preview)preview.innerHTML='<img src="'+reader.result+'" alt="Vista previa">';};reader.readAsDataURL(file);});var add=byId("addNewsButton");if(add)add.addEventListener("click",async function(){var title=byId("newsTitle").value.trim();if(!title){toast("Agrega un titulo");return;}var uploaded=byId("newsUpload")&&byId("newsUpload").dataset.image;var payload={title:title,category:byId("newsCategory").value,day:byId("newsDay").value,image:uploaded||byId("newsImage").value,text:byId("newsText").value.trim()||"Nueva informacion para socios."};if(apiOnline){try{var data=await apiRequest("/api/news",{method:"POST",body:JSON.stringify(payload)});newsItems=data.news||newsItems;}catch(e){toast(e.message);return;}}else{newsItems.unshift(Object.assign({id:Date.now()},payload));persistNews();}renderNews();toast("Novedad publicada");});}
function renderConexionPostural(){var el=byId("conexionPostural");if(!el)return;var ig="https://www.instagram.com/conexionpostural/";el.innerHTML='<section class="conexion-page"><a class="conexion-spotlight panel" href="'+ig+'" target="_blank" rel="noopener noreferrer" aria-label="Abrir Instagram de Conexion Postural"><div class="conexion-brand-copy"><p class="eyebrow">Subseccion OFIT</p><h2>Conexion Postural</h2><p>Marca nacida dentro de OFIT para clases presenciales, virtuales e instructorado de movimiento, postura y conciencia corporal.</p><div class="conexion-actions"><span>Clases presenciales</span><span>Clases virtuales</span><span>Instructorado</span></div><strong>Abrir Instagram</strong></div><figure class="conexion-preview"><img src="assets/conexion-postural-instagram.png" alt="Perfil de Instagram de Conexion Postural"><figcaption>@conexionpostural</figcaption></figure></a><div class="conexion-links"><a class="panel conexion-link-card" href="'+ig+'" target="_blank" rel="noopener noreferrer"><span>01</span><h2>Ver perfil</h2><p>Publicaciones, reels y novedades reales de Conexion Postural.</p></a><a class="panel conexion-link-card" href="'+ig+'" target="_blank" rel="noopener noreferrer"><span>02</span><h2>Consultar clases</h2><p>Entrar al Instagram para escribir y consultar modalidad o horarios.</p></a><a class="panel conexion-link-card" href="'+ig+'" target="_blank" rel="noopener noreferrer"><span>03</span><h2>Instructorado</h2><p>Acceso directo al contenido de formacion y propuestas nuevas.</p></a></div></section>';}
async function bookClass(id){var c=classById(id);var m=state.role==="member"?memberById(state.currentMemberId):selectedOperationalMember("workout");if(!c||!m)return;if(apiOnline){try{var data=await apiRequest("/api/classes/"+c.id+"/book",{method:"POST",body:JSON.stringify({memberId:m.id})});classSessions=data.classes||classSessions;}catch(e){toast(e.message);return;}}else{if(c.booked.indexOf(m.id)<0&&c.booked.length<c.capacity)c.booked.push(m.id);}toast("Cupo reservado: "+c.title);renderAll();showView("routines");}
