function renderSettings(){var activityRows=activities.map(function(a){var classCount=classSessions.filter(function(c){return c.activityId===a.id;}).length;var memberCount=members.filter(function(m){return asList(m.activityIds).indexOf(a.id)>=0;}).length;return '<div class="activity-admin-row"><div><strong>'+a.name+'</strong><small>'+classCount+' clases - '+memberCount+' socios</small></div><button class="danger-button" type="button" data-delete-activity="'+a.id+'">Eliminar</button></div>';}).join("");byId("settings").innerHTML='<div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>Personalizacion simple</h2></div><label class="field"><span>Nombre del gimnasio</span><input id="gymNameInput" value="'+byId("brandName").textContent+'"></label><label class="field"><span>Color principal</span><input id="accentInput" type="color" value="#1f7a5b"></label><button class="primary-button" id="saveBrand" type="button">Guardar vista</button></section><section class="panel settings-wide"><div class="panel-heading"><div><p class="eyebrow">Administracion</p><h2>Actividades</h2></div><span class="tag">'+activities.length+' cargadas</span></div><p class="muted">Al eliminar una actividad tambien se quitan sus clases del calendario y se desasigna de los socios.</p><div class="activity-admin-list">'+activityRows+'</div></section></div>';byId("saveBrand").addEventListener("click",function(){var name=byId("gymNameInput").value.trim()||"Gimnasio Norte";byId("brandName").textContent=name;document.documentElement.style.setProperty("--accent",byId("accentInput").value);});document.querySelectorAll("[data-delete-activity]").forEach(function(button){button.addEventListener("click",function(){deleteActivity(button.dataset.deleteActivity);});});}
function exerciseRows(list,withNote){return list.map(function(ex,i){return '<div class="assigned-row"><span class="tag">'+(i+1)+'</span><span class="exercise-thumb '+ex.thumb+'"></span><span><strong>'+ex.name+'</strong><small>'+ex.sets+' series de '+ex.reps+(ex.weight?' - '+ex.weight+' kg':'')+(withNote?' - '+ex.note:'')+'</small></span></div>';}).join("");}
function formatKg(value){return String(value).replace(/\B(?=(\d{3})+(?!\d))/g,".");}
