function progressLoadData(member,exercise){var base={sentadilla:[32,42],press:[24,34],remo:[16,24],plancha:[25,45],prensa:[55,75],"peso-muerto":[40,58],burpees:[8,14]};var pair=base[exercise.id]||[20,28];var offset=member.id===1?2:member.id===2?-4:0;var start=Math.max(1,pair[0]+offset);var now=Math.max(start+1,pair[1]+offset);return {start:start,now:now,pct:Math.round(((now-start)/start)*100)};}
function initials(name){return name.split(" ").map(function(x){return x[0];}).join("").slice(0,2).toUpperCase();}
async function deleteActivity(id){var activity=activities.find(function(a){return a.id===id;});if(!activity)return;var classCount=classSessions.filter(function(c){return c.activityId===id;}).length;if(!confirm("Eliminar "+activity.name+"? Tambien se borraran "+classCount+" clases asociadas."))return;if(apiOnline){try{var data=await apiRequest("/api/activities/"+encodeURIComponent(id),{method:"DELETE",body:"{}"});activities=data.activities||activities;members=data.members||members;classSessions=data.classes||classSessions;}catch(e){toast(e.message);return;}}else{activities=activities.filter(function(a){return a.id!==id;});members.forEach(function(m){m.activityIds=asList(m.activityIds).filter(function(activityId){return activityId!==id;});});classSessions=classSessions.filter(function(c){return c.activityId!==id;});persistMembers();persistClasses();}renderAll();showView("settings");toast("Actividad eliminada");}
