async function createMemberFromSignup(){var error=byId("signupError");error.textContent="";if(!pendingSignupEmail){await requestSignupCode();return;}var code=byId("signupCode").value.trim();if(!/^\d{6}$/.test(code)){error.textContent="Ingresa el codigo de 6 numeros que recibiste.";return;}try{var data=await apiRequest("/api/register/verify",{method:"POST",body:JSON.stringify({email:pendingSignupEmail,code:code})});activities=data.activities||activities;classSessions=data.classes||classSessions;newsItems=data.news||newsItems;paymentLink=data.paymentLink||paymentLink;paymentInfo=data.paymentInfo||paymentInfo;paymentProofs=data.paymentProofs||paymentProofs;members=[data.member];state.role="member";state.currentMemberId=data.member.id;state.loggedIn=true;document.body.className="logged-in";byId("publicSignupForm").reset();resetSignupVerification();renderNav();renderAll();showView("dashboard");toast("Mail verificado. Ya estas dentro del sistema.");}catch(e){error.textContent=e.message;}}
